namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "Your build completed successfully.",
        "New comment on your pull request.",
        "Deployment to production finished.",
        "A teammate requested your review.",
        "Security scan found 0 vulnerabilities.",
        "Backup completed for database 'main'.",
        "Your subscription renews tomorrow.",
        "New user signed up: user@example.com",
    ];

    public Task<List<Notification>> GetInitialNotificationsAsync()
    {
        var notifications = new List<Notification>();
        lock (_lock)
        {
            for (var i = 0; i < 3; i++)
            {
                notifications.Add(CreateNotification());
            }
        }

        return Task.FromResult(notifications);
    }

    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        // Simulate: ~50 % chance a new notification arrived
        var result = new List<Notification>();
        lock (_lock)
        {
            if (Random.Shared.NextDouble() > 0.5)
            {
                result.Add(CreateNotification());
            }
        }

        return Task.FromResult(result);
    }

    private Notification CreateNotification()
    {
        var id = _nextId++;
        var message = _templates[Random.Shared.Next(_templates.Length)];
        return new Notification(id, message, DateTime.UtcNow);
    }
}

