<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Messages is not null)
    {
        <span class="badge">@Messages.Count</span>
    }
</h1>

@if (Messages is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (Messages.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in Messages)
        {
            <li>
                <strong>@n.Timestamp.ToString("HH:mm:ss")</strong> — @n.Message
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Messages { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when state was NOT restored from prerender
        Messages ??= await NotificationSvc.GetInitialNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never fires during prerender, so this is safe
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newItems = await NotificationSvc.CheckForNewNotificationsAsync();
            if (newItems.Count > 0)
            {
                Messages ??= [];
                Messages.AddRange(newItems);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

